def optional_backend():
    """Probe an installed backend; caller selects a fallback."""
    try:
        import optional_backend
    except ImportError:
        pass


def cleanup(resource):
    try:
        resource.close()
    except OSError:
        # The resource may already be closed; shutdown can continue.
        pass


def recover(cache, key):
    try:
        return cache[key]
    except KeyError:
        return None


def propagate(action):
    try:
        action()
    except RuntimeError:
        raise


def finalized(action, resource):
    try:
        action()
    except ValueError:
        return None
    finally:
        resource.close()


def dispatch(action, handler):
    try:
        action()
    except Exception as error:
        if handler is None:
            raise
        handler(error)
